class NumArray {
    vector<int> prefix;
    public:NumArray(vector<int>& nums):prefix(nums.size()+1){
        for(int i=0;i<(int)nums.size();++i)prefix[i+1]=prefix[i]+nums[i];
    }
    int sumRange(int left,int right){
